(1141, 2, '且', 'qiě', '<副>将要；将近', '天子<b>且</b>至。', '八年级上册｜《周亚夫军细柳》', '天子将要到来。', 1, 0),
(1143, 1, '穷', 'qióng', '<动>尽', '欲<b>穷</b>其林。', '八年级下册｜《桃花源记》', '想要走到那片林子的尽头。', 1, 0),
